package org.dromara.carbon.vendor.domain.license;

import com.fasterxml.jackson.annotation.JsonPropertyOrder;
import lombok.Data;

import java.util.List;

/**
 * Signed license.v1 payload generated by the vendor side.
 */
@Data
@JsonPropertyOrder({
    "licenseId",
    "customerId",
    "customerName",
    "packageId",
    "packageName",
    "edition",
    "features",
    "installId",
    "validFrom",
    "validTo",
    "issuedAt",
    "issuer",
    "keyId",
    "templateEntitlements"
})
public class CvLicensePayload {

    private String licenseId;

    private String customerId;

    private String customerName;

    private Long packageId;

    private String packageName;

    private String edition;

    private List<String> features;

    private String installId;

    private String validFrom;

    private String validTo;

    private String issuedAt;

    private String issuer;

    private String keyId;

    private List<CvTemplateEntitlement> templateEntitlements;
}
